import { test, expect } from '@playwright/test';

test.describe('Modal Close by Escape Key', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal');
  });

  test('should close modal when Escape key is pressed', async ({ page }) => {
    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify modal has close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify modal has content
    const modalContent = page.locator('[data-testid="modal-content"]');
    await expect(modalContent).toBeVisible();

    // Press Escape key
    await page.keyboard.press('Escape');

    // Verify modal is closed
    await expect(modal).not.toBeVisible();

    // Verify close button is disabled
    await expect(closeButton).toBeDisabled();

    // Verify page content is visible
    const pageContent = page.getByRole('main');
    await expect(pageContent).toBeVisible();
  });

  test('should not close modal when Escape key is pressed outside modal', async ({ page }) => {
    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify modal has close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify modal has content
    const modalContent = page.locator('[data-testid="modal-content"]');
    await expect(modalContent).toBeVisible();

    // Press Escape key
    await page.keyboard.press('Escape');

    // Verify modal is still visible
    await expect(modal).toBeVisible();

    // Verify close button is still enabled
    await expect(closeButton).toBeEnabled();

    // Verify modal content is still visible
    await expect(modalContent).toBeVisible();
  });
});
